#pragma once#include <TinyXmlReader.h>template<typename DERIVED, typename tType>class KXmlReader2{protected:  DERIVED *m_pParent;  int m_Type12;public:  typedef void (DERIVED::*pfHandlerT)( tinyxml2::XMLElementPtr &item, tType arg1 );  typedef std::map<std::string, pfHandlerT> tHandlersContT_;public:  typedef struct tSHandler  {    LPCSTR pszKey;    pfHandlerT pCall;  }SHandler;public:  tHandlersContT_ cont;protected:  const SHandler *m_pHandlers;  size_t m_S;  typedef int (*tStrComparator)( LPCSTR lpString1, LPCSTR lpString2 );public:  KXmlReader2(DERIVED *pParent) : m_pParent(pParent), m_pHandlers(NULL), m_S(0), m_Type12(1)  {}  template<size_t _S>  KXmlReader2(DERIVED *pParent, const SHandler (&cont)[_S]) : m_pParent(pParent), m_pHandlers(cont), m_S(_S), m_Type12(2)  {}  void Read( tinyxml2::XMLElementPtr &root, tType arg1, bool bControlNames = true )  {    if( 1==m_Type12 )      ReadImpl1( root, arg1, bControlNames );    else if( 2==m_Type12 )      ReadImpl2( root, arg1, bControlNames );  }  template<size_t _S>  void Read( tinyxml2::XMLElementPtr &root, tType arg1, const SHandler (&cont)[_S], bool bControlNames = true )  {    m_pHandlers =cont;    m_S =_S;    m_Type12 = 2;    ReadImpl2( root, arg1, bControlNames );  }private:  void ReadImpl1( tinyxml2::XMLElementPtr &root, tType arg1, bool bControlNames = true )  {    using namespace tinyxml2;    for( XMLElementPtr item = root->FirstChildElement(); item != NULL; item = item->NextSiblingElement() )    {      LPCSTR element_name = item->Name();      tHandlersContT_::iterator it = cont.find( element_name );      if( bControlNames )      {        ASS( cont.end()!=it );      }      if( cont.end()==it )        continue;      pfHandlerT pCall = it->second;      ((m_pParent)->*(pCall))(item, arg1);    }  }  const SHandler *find( LPCSTR pszKey, tStrComparator pfnCompare = strcmp )  {    if( !m_pHandlers )      return NULL;    for( size_t i=0; i<m_S; ++i )    {      if( !pfnCompare(pszKey, m_pHandlers[i].pszKey) )        return &m_pHandlers[i];    }    return NULL;  }  void ReadImpl2( tinyxml2::XMLElementPtr &root, tType arg1, bool bControlNames = true )  {    using namespace tinyxml2;    for( XMLElementPtr item = root->FirstChildElement(); item != NULL; item = item->NextSiblingElement() )    {      LPCSTR element_name = item->Name();      const SHandler *pH = find( element_name );      if( bControlNames )      {        ASS( pH );      }      if( !pH )        continue;      pfHandlerT pCall = pH->pCall;      ((m_pParent)->*(pCall))(item, arg1);    }  }};template<typename DERIVED, typename tType, typename tType2>class KXmlReader3{protected:  DERIVED *m_pParent;public:  typedef void (DERIVED::*pfHandlerT)( tinyxml2::XMLElementPtr &item, tType arg1, tType2 arg2 );  typedef std::map<std::string, pfHandlerT> tHandlersContT_;public:  typedef struct tSHandler  {    LPCSTR pszKey;    pfHandlerT pCall;  }SHandler;public:  tHandlersContT_ cont;public:  KXmlReader3(DERIVED *pParent) : m_pParent(pParent)  {}  template<size_t _S>  void Read( tinyxml2::XMLElementPtr &root, tType arg1, tType2 arg2, const SHandler (&cont)[_S], bool bControlNames = true )  {    using namespace tinyxml2;    for( XMLElementPtr item = root->FirstChildElement(); item != NULL; item = item->NextSiblingElement() )    {      LPCSTR element_name = item->Name();      const SHandler *pH = find( element_name, cont );      if( bControlNames )      {        ASS( pH );      }      if( !pH )        continue;      pfHandlerT pCall = pH->pCall;      ((m_pParent)->*(pCall))(item, arg1, arg2);    }  }  void Read( tinyxml2::XMLElementPtr &root, tType arg1, tType2 arg2, bool bControlNames = true )  {    using namespace tinyxml2;    for( XMLElementPtr item = root->FirstChildElement(); item != NULL; item = item->NextSiblingElement() )    {      LPCSTR element_name = item->Name();      tHandlersContT_::iterator it = cont.find( element_name );      if( bControlNames )      {        ASS( cont.end()!=it );      }      if( cont.end()==it )        continue;      pfHandlerT pCall = it->second;      ((m_pParent)->*(pCall))(item, arg1, arg2);    }  }private:  template<size_t _S>  const SHandler *find( LPCSTR pszKey, const SHandler (&cont)[_S] )  {    for( size_t i=0; i<_S; ++i )    {      if( !strcmp(pszKey, cont[i].pszKey) )        return &cont[i];    }    return NULL;  }};